import { chromium } from 'playwright';
const B='https://osaraclinics.com'; const tests=[['/dermatology','[data-appointment]','appointment_click'],['/dermatology','.whatsapp-float','whatsapp_click'],['/ophthalmology','a[href^="tel:"]','phone_click'],['/ophthalmology','a[href*="google.com/maps"]','directions_click']]; let errors=[]; let out={}; const browser=await chromium.launch({headless:true}); const ctx=await browser.newContext({viewport:{width:390,height:844}});
for(const [route,sel,name] of tests){ const p=await ctx.newPage(); let loader=false; p.on('request',r=>{if(r.url().includes('googletagmanager.com/gtag/js?id=G-72BY7LC2V2')) loader=true}); await p.goto(B+route,{waitUntil:'networkidle',timeout:60000}); await p.waitForTimeout(500); const ready=await p.evaluate(()=>typeof window.gtag==='function'); if(!ready||!loader) errors.push(`${route} GA4 inactive`); await p.evaluate(()=>{window.__pr4calls=[]; const orig=window.gtag; window.gtag=function(){window.__pr4calls.push(Array.from(arguments)); return orig.apply(this,arguments);};}); await p.locator(sel).first().click({noWaitAfter:true}); await p.waitForTimeout(300); const calls=await p.evaluate(()=>window.__pr4calls||[]); const count=calls.filter(x=>x[0]==='event'&&x[1]===name).length; out[name]={count,calls}; if(count!==1) errors.push(`${name} count ${count}`); await p.close(); }
console.log(JSON.stringify({out,errors},null,2)); await browser.close(); process.exit(errors.length?1:0);